const rawOutput = $json.text;

// 1. Parse Gemini's JSON response
let meetingData;

try {
  meetingData = JSON.parse(rawOutput);
} catch (error) {
  throw new Error(
    "Invalid JSON received from Gemini: " + error.message
  );
}

// 2. Validate required top-level fields
const requiredFields = [
  "meeting_title",
  "meeting_summary",
  "discussion_points",
  "decisions",
  "action_items",
  "open_questions",
  "clarifications_required",
  "conflicts_detected",
  "risks"
];

for (const field of requiredFields) {
  if (!(field in meetingData)) {
    throw new Error(`Missing required field: ${field}`);
  }
}

// 3. Validate array fields
const arrayFields = [
  "discussion_points",
  "decisions",
  "action_items",
  "open_questions",
  "clarifications_required",
  "conflicts_detected",
  "risks"
];

for (const field of arrayFields) {
  if (!Array.isArray(meetingData[field])) {
    throw new Error(`${field} must be an array`);
  }
}

// 4. Validate individual action items
for (const [index, item] of meetingData.action_items.entries()) {
  const requiredActionFields = [
    "task",
    "owner",
    "deadline",
    "deadline_status",
    "owner_status",
    "priority"
  ];

  for (const field of requiredActionFields) {
    if (!(field in item)) {
      throw new Error(
        `Action item ${index + 1} is missing ${field}`
      );
    }
  }

  if (!["Confirmed", "Missing", "Ambiguous"].includes(item.deadline_status)) {
    throw new Error(`Invalid deadline_status in action item ${index + 1}`);
  }

  if (!["Assigned", "Missing"].includes(item.owner_status)) {
    throw new Error(`Invalid owner_status in action item ${index + 1}`);
  }

  if (!["High", "Medium", "Low", "Unknown"].includes(item.priority)) {
    throw new Error(`Invalid priority in action item ${index + 1}`);
  }
}

// 5. Validate conflict and risk records
for (const [index, conflict] of meetingData.conflicts_detected.entries()) {
  if (
    typeof conflict.conflict !== "string" ||
    !Array.isArray(conflict.involved_participants) ||
    typeof conflict.explanation !== "string" ||
    !["High", "Medium", "Low"].includes(conflict.severity)
  ) {
    throw new Error(`Invalid conflict record at index ${index}`);
  }
}

for (const [index, risk] of meetingData.risks.entries()) {
  if (
    typeof risk.risk !== "string" ||
    typeof risk.reason !== "string" ||
    !["High", "Medium", "Low"].includes(risk.severity)
  ) {
    throw new Error(`Invalid risk record at index ${index}`);
  }
}

// 6. Retrieve normalized input metadata
const telegramData = $("Edit Fields").isExecuted
  ? $("Edit Fields").item.json
  : $("Edit Fields1").item.json;

// 7. Generate a deterministic meeting ID
const meetingId =
  `M-${telegramData.chat_id}-${telegramData.message_id}`;

// 8. Return the complete structured output
return {
  json: {
    ...telegramData,
    ...meetingData,
    meeting_id: meetingId
  }
};

const inputItems = $input.all();

function formatList(items, emptyMessage = "None identified") {
  if (!Array.isArray(items) || items.length === 0) {
    return emptyMessage;
  }

  return items.map((item, i) => `${i + 1}. ${item}`).join("\n");
}

function formatActionItems(items) {
  if (!Array.isArray(items) || items.length === 0) {
    return "No action items identified.";
  }

  return items.map((item, i) =>
    `${i + 1}. ${item.task}
   Owner: ${item.owner || "Unassigned"}
   Deadline: ${item.deadline || "Not specified"}
   Priority: ${item.priority || "Unknown"}
   Status: ${item.owner_status || "Unknown"} / ${item.deadline_status || "Unknown"}`
  ).join("\n\n");
}

function formatConflicts(items) {
  if (!Array.isArray(items) || items.length === 0) {
    return "No conflicts detected.";
  }

  return items.map((item, i) =>
    `${i + 1}. ${item.conflict} [${item.severity}]
   ${item.explanation}
   Participants: ${(item.involved_participants || []).join(", ") || "Not specified"}`
  ).join("\n\n");
}

function formatRisks(items) {
  if (!Array.isArray(items) || items.length === 0) {
    return "No risks detected.";
  }

  return items.map((item, i) =>
    `${i + 1}. ${item.risk} [${item.severity}]
   ${item.reason}`
  ).join("\n\n");
}

const output = [];

for (const input of inputItems) {
  const data = input.json;

  const report = [
    "MEETING ANALYSIS REPORT",
    "=======================",
    `Meeting: ${data.meeting_title}`,
    `Meeting ID: ${data.meeting_id}`,
    "",
    "MEETING SUMMARY",
    data.meeting_summary || "Not available.",
    "",
    "DECISIONS",
    formatList(data.decisions),
    "",
    "ACTION ITEMS",
    formatActionItems(data.action_items),
    "",
    "OPEN QUESTIONS",
    formatList(data.open_questions),
    "",
    "CLARIFICATIONS REQUIRED",
    formatList(data.clarifications_required),
    "",
    "CONFLICTS DETECTED",
    formatConflicts(data.conflicts_detected),
    "",
    "POTENTIAL RISKS",
    formatRisks(data.risks)
  ].join("\n");

  // Split into messages without cutting words or lines.
  const maxLength = 3900;
  const chunks = [];
  let currentChunk = "";

  for (const line of report.split("\n")) {
    if (currentChunk.length + line.length + 1 > maxLength) {
      chunks.push(currentChunk);
      currentChunk = "";
    }

    currentChunk += (currentChunk ? "\n" : "") + line;
  }

  if (currentChunk) {
    chunks.push(currentChunk);
  }

  chunks.forEach((chunk, index) => {
    const message = chunks.length > 1
      ? `PART ${index + 1}/${chunks.length}\n\n${chunk}`
      : chunk;

    output.push({
      json: {
        chat_id: data.chat_id,
        report_text: message,
        meeting_id: data.meeting_id,
        part: index + 1,
        total_parts: chunks.length
      }
    });
  });
}

return output;

const rawOutput = $json.text;

let result;

try {
  result = JSON.parse(rawOutput);
} catch (error) {
  throw new Error("Classifier returned invalid JSON: " + error.message);
}

const allowedCategories = [
  "VALID_TRANSCRIPT",
  "INVALID_INPUT",
  "UNCLEAR_INPUT"
];

if (!allowedCategories.includes(result.classification)) {
  throw new Error("Unexpected classification: " + result.classification);
}

const originalData = $("Edit Fields").isExecuted
  ? $("Edit Fields").item.json
  : $("Edit Fields1").item.json;

return {
  json: {
    ...originalData,
    classification: result.classification,
    classification_reason: result.reason
  }
};
